Here are modern MSTest data-driven tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // --- DataRow: inline values for simple combinations ---

    [TestMethod]
    [DataRow(1, 9.99, 9.99, DisplayName = "Single item")]
    [DataRow(5, 10.00, 50.00, DisplayName = "Multiple items")]
    [DataRow(0, 25.00, 0.00, DisplayName = "Zero quantity")]
    [DataRow(1, 0.00, 0.00, DisplayName = "Zero price")]
    [DataRow(100, 1.50, 150.00, DisplayName = "Large quantity")]
    public void CalculateTotal_ReturnsExpectedAmount(
        int quantity, double unitPrice, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)unitPrice);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1, 10.00)]
    [DataRow(1, -5.00)]
    public void CalculateTotal_NegativeInput_ThrowsArgumentException(
        int quantity, double unitPrice)
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _calculator.CalculateTotal(quantity, (decimal)unitPrice));
    }

    // --- DynamicData with ValueTuples: preferred for complex/decimal data ---

    [TestMethod]
    [DynamicData(nameof(DiscountData))]
    public void ApplyDiscount_ReturnsExpectedPrice(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)> DiscountData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m,  0,  50m),
        (80m,  100, 0m),
        (99.99m, 50, 49.995m),
    ];

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData))]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRangeException(
        decimal price, int discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    public static IEnumerable<(decimal price, int discountPercent)> InvalidDiscountData =>
    [
        (100m, -1),
        (100m, 101),
    ];
}
```

**Key practices used:**

- **`sealed` test class** — performance and design clarity
- **`DataRow`** — inline values for simple primitive combinations; `DisplayName` for readable test names
- **`DynamicData` with ValueTuples** (MSTest 3.7+) — type-safe, avoids `object[]` boxing, ideal for `decimal` data that `DataRow` can't express directly
- **`Assert.ThrowsExactly<T>`** — replaces `[ExpectedException]`, lets you inspect the exception
- **Constructor init** — enables `readonly` fields
- **`[TestMethod]`** only — no legacy `[DataTestMethod]` needed (MSTEST0044)

> **Note:** `DataRow` only supports compile-time constants (`int`, `double`, `string`, `bool`). Use `DynamicData` for `decimal`, complex objects, or when you want named tuple parameters.
